<?php
declare(strict_types=1);
require_once dirname(__DIR__,2).'/config.php';require_once dirname(__DIR__,2).'/database/config/db.php';require_once dirname(__DIR__,2).'/security/middleware/AuthMiddleware.php';require_once dirname(__DIR__,2).'/services/MessageService.php';
header('Content-Type: application/json');AuthMiddleware::startSession();$user=AuthMiddleware::requireAuth(true);if($_SERVER['REQUEST_METHOD']!=='POST'&&$_SERVER['REQUEST_METHOD']!=='DELETE'){http_response_code(405);echo json_encode(['error'=>'Method not allowed']);exit;}AuthMiddleware::verifyCsrf();
try{$body=json_decode(file_get_contents('php://input'),true)??$_POST;$messageId=filter_var($body['message_id']??0,FILTER_VALIDATE_INT);if(!$messageId){http_response_code(400);echo json_encode(['error'=>'message_id is required']);exit;}$db=Database::getInstance();$roleStmt=$db->prepare('SELECT role FROM users WHERE id=:uid AND deleted_at IS NULL LIMIT 1');$roleStmt->execute([':uid'=>$user['id']]);$role=(string)($roleStmt->fetchColumn()?:'student');(new MessageService())->deleteMessage((int)$messageId,(int)$user['id'],$role);echo json_encode(['success'=>true,'message_id'=>$messageId]);}catch(Throwable $e){$code=($e->getCode()>=400&&$e->getCode()<600)?$e->getCode():500;http_response_code($code);echo json_encode(['error'=>$code<500?$e->getMessage():'Server error']);}
